-- 0025_fy_targets.sql
--
-- The financial-year targets, and nothing else.
--
-- Decided by Dr Raghu: targets are FY-wide (not monthly, not quarterly), and
-- only raghu@nandan.co.in may change them. Everyone else reads them as fixed,
-- which is the point -- a target the board can edit is not a target.
--
-- One row per financial year, keyed by the label the rest of the suite already
-- uses (fyLabel() in src/lib/delivered.ts -> "FY2026-27"). Keyed by year rather
-- than a singleton so last year's target survives the roll-over: on 1 April the
-- app looks up the new FY, finds nothing, and says "no target set" instead of
-- silently measuring this year against last year's number.
--
-- Amounts are plain rupees, like every other value in the suite. 100 Cr is
-- 1000000000. The UI does the Cr formatting.
--
-- Additive and safe to re-run.

create table if not exists public.fy_targets (
  fy                text primary key,
  sales_target      numeric not null default 0,
  throughput_target numeric not null default 0,
  updated_at        timestamptz not null default now(),
  updated_by        uuid references public.profiles(id),
  constraint fy_targets_sales_nonneg      check (sales_target >= 0),
  constraint fy_targets_throughput_nonneg check (throughput_target >= 0)
);

-- FY2026-27, as given: sales 100 Cr, throughput 40 Cr.
-- on conflict do nothing, so re-running never overwrites an edited target.
insert into public.fy_targets (fy, sales_target, throughput_target)
values ('FY2026-27', 1000000000, 400000000)
on conflict (fy) do nothing;

alter table public.fy_targets enable row level security;

-- Everyone signed in reads them: the run-rate card is on the Job Delivery
-- Board and on Delivered Jobs, which every role can open.
drop policy if exists fy_targets_read on public.fy_targets;
create policy fy_targets_read on public.fy_targets
  for select to authenticated
  using (true);

-- Only the owner writes. is_owner() is the same helper the goals tier uses
-- (migration 0011); the API route gates on it too, and this is the backstop
-- that survives a mistake in application code.
drop policy if exists fy_targets_write on public.fy_targets;
create policy fy_targets_write on public.fy_targets
  for all to authenticated
  using (public.is_owner())
  with check (public.is_owner());

comment on table public.fy_targets is
  'FY-wide sales and throughput targets, one row per financial year. '
  'Owner-only writes. Drives the Required Run Rate card.';


-- >>>>> supabase/migrations/0026_job_money_and_hint_cache.sql
-- 0026_job_money_and_hint_cache.sql
--
-- 1. The money side of a job, from the Jobmaster export.
--
--    A job has always been read here as dates, throughput and kitting -- what
--    it costs to build and when it goes out. What it does to the bank has been
--    missing entirely, so "which job should we finish first" could only ever be
--    answered on delivery pressure, never on cash. These four columns are in
--    the Jobmaster export; Genie simply never read them.
--
--    Matched by MEANING, not by exact header (see EXTRA_JOB_FIELDS in
--    src/lib/parse-upload.ts), and the upload summary names the header each one
--    matched -- the same way the delivered-date column was confirmed. If a
--    header does not match, the field stays null and the summary says so
--    rather than the number silently reading zero.
--
-- 2. A SHARED cache for the Genie hint.
--
--    The hint was cached in a JavaScript Map in module scope. On Vercel every
--    serverless instance holds its own, so the second person to open a job paid
--    for a whole fresh generation, and a cold start threw the lot away. That is
--    why it read as "click it again for each person". A row in Postgres is one
--    cache for everybody: the first person to open a job pays, everyone else
--    reads what they paid for.
--
-- Additive and safe to re-run.

-- ---------------------------------------------------------------------------
-- 1. Job money fields
-- ---------------------------------------------------------------------------
alter table public.jobs add column if not exists client_update    text;
alter table public.jobs add column if not exists cashflow         text;
alter table public.jobs add column if not exists amt_needed       numeric;
alter table public.jobs add column if not exists pay_on_delivery  numeric;

comment on column public.jobs.client_update is
  'Latest word from the customer, from the Jobmaster export. Free text.';
comment on column public.jobs.cashflow is
  'Cash flow note for this job, from the Jobmaster export. Free text.';
comment on column public.jobs.amt_needed is
  'Amount still needed to finish the job, in rupees.';
comment on column public.jobs.pay_on_delivery is
  'Payment that falls due when this job is delivered, in rupees. Sortable on '
  'the job list: it is what makes "finish this one next" a cash decision.';

-- Sorting the board by what is collectable on delivery is the whole point of
-- carrying the column, so it gets an index.
create index if not exists jobs_pay_on_delivery_idx
  on public.jobs (pay_on_delivery desc nulls last) where active;

-- ---------------------------------------------------------------------------
-- 1b. apply_jobs carries the money fields -- and only when the sheet had them
-- ---------------------------------------------------------------------------
-- p_money_fields lists the keys the parser actually BOUND to a header on this
-- sheet. A field not in that list is left exactly as it was banked, so an
-- export that drops a column (or a second export that never carried it) cannot
-- wipe a payment figure to null. Writing an explicit null when the column IS
-- present is correct: that means the cell was blank today.
--
-- The old two-argument signature is dropped rather than left beside this one:
-- two overloads differing only by a defaulted argument make every existing
-- call ambiguous.
drop function if exists public.apply_jobs(jsonb, uuid);

create or replace function public.apply_jobs(
  p_jobs jsonb,
  p_batch uuid,
  p_money_fields text[] default '{}'
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  ids text[];
begin
  if p_jobs is null or jsonb_array_length(p_jobs) = 0 then
    return;  -- never archive the whole board on an empty payload
  end if;

  select coalesce(array_agg(j ->> 'id'), '{}') into ids
  from jsonb_array_elements(p_jobs) j;

  insert into public.jobs
    (id, tag, fam, cust, val, tdd, otd, start_date, proj, stat, pct, note,
     own, mgmt, tp, tpv, tpp, kit, active, archived_at, updated_batch,
     client_update, cashflow, amt_needed, pay_on_delivery)
  select
    j ->> 'id',
    j ->> 'tag',
    j ->> 'fam',
    j ->> 'cust',
    coalesce((j ->> 'val')::numeric, 0),
    nullif(j ->> 'tdd', '')::date,
    nullif(j ->> 'otd', '')::date,
    nullif(j ->> 'start', '')::date,
    j ->> 'proj',
    j ->> 'stat',
    coalesce((j ->> 'pct')::numeric, 0),
    j ->> 'note',
    j ->> 'own',
    nullif(j ->> 'mgmt', '')::date,
    coalesce((j ->> 'tp')::numeric, 0),
    coalesce((j ->> 'tpv')::numeric, 0),
    coalesce((j ->> 'tpp')::numeric, 0),
    coalesce((j ->> 'kit')::numeric, 0),
    true, null, p_batch,
    j ->> 'clientUpdate',
    j ->> 'cashflow',
    nullif(j ->> 'amtNeeded', '')::numeric,
    nullif(j ->> 'payOnDelivery', '')::numeric
  from jsonb_array_elements(p_jobs) j
  on conflict (id) do update set
    tag = excluded.tag, fam = excluded.fam, cust = excluded.cust,
    val = excluded.val, tdd = excluded.tdd, otd = excluded.otd,
    start_date = excluded.start_date, proj = excluded.proj,
    stat = excluded.stat, pct = excluded.pct, note = excluded.note,
    own = excluded.own, mgmt = excluded.mgmt, tp = excluded.tp,
    tpv = excluded.tpv, tpp = excluded.tpp, kit = excluded.kit,
    active = true, archived_at = null, updated_batch = excluded.updated_batch,
    client_update = case when 'clientUpdate' = any (p_money_fields)
                         then excluded.client_update else jobs.client_update end,
    cashflow = case when 'cashflow' = any (p_money_fields)
                    then excluded.cashflow else jobs.cashflow end,
    amt_needed = case when 'amtNeeded' = any (p_money_fields)
                      then excluded.amt_needed else jobs.amt_needed end,
    pay_on_delivery = case when 'payOnDelivery' = any (p_money_fields)
                           then excluded.pay_on_delivery else jobs.pay_on_delivery end;

  -- jobs that left the export are archived, never deleted (plans stay reachable)
  update public.jobs
    set active = false, archived_at = now()
    where active = true and not (id = any (ids));

  -- priority_order: drop archived ids, keep order (new jobs appended at read time)
  update public.settings
    set priority_order = coalesce((
      select array_agg(x order by ord)
      from unnest(priority_order) with ordinality as t(x, ord)
      where x = any (ids)
    ), '{}')
    where id = 1;
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. Genie hint cache, shared by everyone
-- ---------------------------------------------------------------------------
-- No foreign key to jobs on purpose: this is a cache, and a stale row for a
-- job that has gone is harmless, whereas a delete that fails because a cache
-- row exists is not.
create table if not exists public.job_hint (
  job_id     text primary key,
  hint       jsonb not null,
  built_at   timestamptz not null default now(),
  -- who paid for it, so the panel can say whose read this is and when
  built_by   text,
  -- the model that wrote it: a hint from an older model should be re-read
  -- rather than trusted forever
  model      text
);

create index if not exists job_hint_built_at_idx on public.job_hint (built_at desc);

alter table public.job_hint enable row level security;

-- Everyone signed in reads it. Writes go through the service role in
-- /api/genie-hint, which is the only thing that can afford to write one.
drop policy if exists job_hint_read on public.job_hint;
create policy job_hint_read on public.job_hint
  for select to authenticated
  using (true);

comment on table public.job_hint is
  'Shared cache of the written Genie brief, one row per job. Replaces a '
  'per-instance in-memory Map that made every reader pay for their own copy.';


-- >>>>> supabase/migrations/0027_lms.sql
-- 0027_lms.sql
--
-- The Learning Management section.
--
-- The shape, and why it is this shape:
--
--   A LESSON IS NOT OWNED BY A BOOK. "Use of Digital Tools" and "Design
--   Training" both want the same CAD lesson, and copying it means two lessons
--   that drift apart until one is wrong. So lesson-in-book is its own table,
--   and the SECTION a lesson sits in lives there too -- the same lesson can be
--   filed under "Basics" in one book and "Refresher" in another.
--
--   PROGRESS IS PER PERSON, PER LESSON. Status, the date it was finished, the
--   minutes it took and what the person actually wrote down are one row. That
--   row is the unit the IDP adds up.
--
--   WHAT SOMEBODY LEARNED IS NOT OPTIONAL. A lesson cannot be marked complete
--   without at least fifty words in their own words. A tick box records
--   attendance; fifty words record learning, and the whole point of this
--   section is that the second one ends up in the IDP.
--
--   TRAINING TAKEN ELSEWHERE STILL COUNTS. lms_extra is where a course, a
--   seminar or a site visit goes, so a person's total is their real total and
--   not just the part Genie happened to publish.
--
-- ASCII only, and safe to re-run.

-- ---------------------------------------------------------------------------
-- Books -- the shelves
-- ---------------------------------------------------------------------------
create table if not exists public.lms_book (
  id         text primary key,          -- stable slug, e.g. 'wcm-kaizen'
  name       text not null,
  blurb      text,
  icon       text,                      -- one emoji, shown on the shelf
  color      text not null default '#1B3A5C',
  sort_order int  not null default 0,
  active     boolean not null default true,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Sections inside a book
-- ---------------------------------------------------------------------------
create table if not exists public.lms_section (
  id         uuid primary key default gen_random_uuid(),
  book_id    text not null references public.lms_book(id) on delete cascade,
  name       text not null,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists lms_section_book_idx on public.lms_section (book_id, sort_order);

-- ---------------------------------------------------------------------------
-- Lessons -- authored once, shelved anywhere
-- ---------------------------------------------------------------------------
create table if not exists public.lms_lesson (
  id          uuid primary key default gen_random_uuid(),
  title       text not null,
  -- the body. Markdown, so it can be written in a text box and still carry
  -- headings, lists and links without an editor nobody asked for.
  content     text not null default '',
  description text not null default '',
  -- a PDF is a first-class body, not a link buried in the text: handbooks and
  -- ISO documents ARE pdfs, and this is the field that embeds one
  pdf_url     text,
  -- YouTube or a Drive share link. The player is rebuilt in the app so the
  -- viewer gets play, pause, forward and the clock and nothing else.
  video_url   text,
  -- how long the lesson should take. The minutes a person actually banks are
  -- on their progress row, because those are two different facts.
  minutes     int not null default 0,
  active      boolean not null default true,
  created_by  uuid references public.profiles(id),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint lms_lesson_minutes_sane check (minutes >= 0 and minutes <= 10000)
);

-- ---------------------------------------------------------------------------
-- Which books a lesson appears in, and where inside each
-- ---------------------------------------------------------------------------
create table if not exists public.lms_lesson_book (
  lesson_id  uuid not null references public.lms_lesson(id) on delete cascade,
  book_id    text not null references public.lms_book(id)   on delete cascade,
  -- null means "loose in the book", which is a real state: a lesson lands in a
  -- book before anybody has decided which section it belongs to
  section_id uuid references public.lms_section(id) on delete set null,
  sort_order int not null default 0,
  primary key (lesson_id, book_id)
);
create index if not exists lms_lesson_book_book_idx on public.lms_lesson_book (book_id, sort_order);

-- ---------------------------------------------------------------------------
-- Progress -- one row per person per lesson
-- ---------------------------------------------------------------------------
create table if not exists public.lms_progress (
  person_id    uuid not null references public.profiles(id) on delete cascade,
  lesson_id    uuid not null references public.lms_lesson(id) on delete cascade,
  status       text not null default 'planned',
  completed_on date,
  -- their own words. The fifty-word floor is enforced in the API, where the
  -- message can explain itself; the constraint here is the backstop.
  learning     text not null default '',
  -- minutes this person actually spent, which may not be the lesson's estimate
  minutes      int not null default 0,
  -- who put it on their plan: 'genie', 'self', or an admin's name
  planned_by   text,
  updated_at   timestamptz not null default now(),
  primary key (person_id, lesson_id),
  constraint lms_progress_status check (status in ('planned', 'in_progress', 'completed')),
  constraint lms_progress_minutes_sane check (minutes >= 0 and minutes <= 10000),
  -- completed means finished: a date and something written down
  constraint lms_progress_complete_is_complete
    check (status <> 'completed' or (completed_on is not null and length(btrim(learning)) > 0))
);
create index if not exists lms_progress_person_idx on public.lms_progress (person_id, status);
create index if not exists lms_progress_lesson_idx on public.lms_progress (lesson_id);

-- ---------------------------------------------------------------------------
-- Training taken outside Genie
-- ---------------------------------------------------------------------------
create table if not exists public.lms_extra (
  id         uuid primary key default gen_random_uuid(),
  person_id  uuid not null references public.profiles(id) on delete cascade,
  title      text not null,
  provider   text,
  on_date    date,
  minutes    int not null default 0,
  learning   text not null default '',
  created_at timestamptz not null default now(),
  constraint lms_extra_minutes_sane check (minutes >= 0 and minutes <= 100000)
);
create index if not exists lms_extra_person_idx on public.lms_extra (person_id, on_date desc);

-- ---------------------------------------------------------------------------
-- The Learning Plan -- one per person, written by Genie
-- ---------------------------------------------------------------------------
create table if not exists public.lms_plan (
  person_id    uuid primary key references public.profiles(id) on delete cascade,
  plan         text not null default '',
  -- the reasoning Genie gave, kept beside the plan so a person can see why
  -- these lessons and not others
  rationale    text not null default '',
  generated_at timestamptz not null default now(),
  generated_by text
);

