-- >>>>> supabase/migrations/0028_escalation_and_goal_category.sql
-- 0028_escalation_and_goal_category.sql
--
-- 1. Current Project Escalation, from the Jobmaster. It belongs beside the
--    status and the money on the job page: what is holding a job up is the
--    other half of what it is worth.
--
-- 2. A category on every goal, sub-goal and initiative -- pointed at the
--    swimlanes table that has existed since 0010 and is already managed from
--    Admin. A free-text category would have become fifteen spellings of
--    "Operations" inside a month; a foreign key cannot.
--
-- Additive and safe to re-run.

-- ---------------------------------------------------------------------------
-- 1. Escalation on a job
-- ---------------------------------------------------------------------------
alter table public.jobs add column if not exists escalation text;

comment on column public.jobs.escalation is
  'Current Project Escalation from the Jobmaster export. Free text: what is '
  'holding this job up, in the words of whoever raised it.';

-- ---------------------------------------------------------------------------
-- 1b. apply_jobs carries it, on the same per-sheet rule as the money fields
-- ---------------------------------------------------------------------------
-- A column absent from today's export must never blank what is already banked,
-- so escalation joins p_money_fields rather than being written unconditionally.
drop function if exists public.apply_jobs(jsonb, uuid, text[]);

create or replace function public.apply_jobs(
  p_jobs jsonb,
  p_batch uuid,
  p_money_fields text[] default '{}'
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  ids text[];
begin
  if p_jobs is null or jsonb_array_length(p_jobs) = 0 then
    return;
  end if;

  select coalesce(array_agg(j ->> 'id'), '{}') into ids
  from jsonb_array_elements(p_jobs) j;

  insert into public.jobs
    (id, tag, fam, cust, val, tdd, otd, start_date, proj, stat, pct, note,
     own, mgmt, tp, tpv, tpp, kit, active, archived_at, updated_batch,
     client_update, cashflow, amt_needed, pay_on_delivery, escalation)
  select
    j ->> 'id',
    j ->> 'tag',
    j ->> 'fam',
    j ->> 'cust',
    coalesce((j ->> 'val')::numeric, 0),
    nullif(j ->> 'tdd', '')::date,
    nullif(j ->> 'otd', '')::date,
    nullif(j ->> 'start', '')::date,
    j ->> 'proj',
    j ->> 'stat',
    coalesce((j ->> 'pct')::numeric, 0),
    j ->> 'note',
    j ->> 'own',
    nullif(j ->> 'mgmt', '')::date,
    coalesce((j ->> 'tp')::numeric, 0),
    coalesce((j ->> 'tpv')::numeric, 0),
    coalesce((j ->> 'tpp')::numeric, 0),
    coalesce((j ->> 'kit')::numeric, 0),
    true, null, p_batch,
    j ->> 'clientUpdate',
    j ->> 'cashflow',
    nullif(j ->> 'amtNeeded', '')::numeric,
    nullif(j ->> 'payOnDelivery', '')::numeric,
    j ->> 'escalation'
  from jsonb_array_elements(p_jobs) j
  on conflict (id) do update set
    tag = excluded.tag, fam = excluded.fam, cust = excluded.cust,
    val = excluded.val, tdd = excluded.tdd, otd = excluded.otd,
    start_date = excluded.start_date, proj = excluded.proj,
    stat = excluded.stat, pct = excluded.pct, note = excluded.note,
    own = excluded.own, mgmt = excluded.mgmt, tp = excluded.tp,
    tpv = excluded.tpv, tpp = excluded.tpp, kit = excluded.kit,
    active = true, archived_at = null, updated_batch = excluded.updated_batch,
    client_update = case when 'clientUpdate' = any (p_money_fields)
                         then excluded.client_update else jobs.client_update end,
    cashflow = case when 'cashflow' = any (p_money_fields)
                    then excluded.cashflow else jobs.cashflow end,
    amt_needed = case when 'amtNeeded' = any (p_money_fields)
                      then excluded.amt_needed else jobs.amt_needed end,
    pay_on_delivery = case when 'payOnDelivery' = any (p_money_fields)
                           then excluded.pay_on_delivery else jobs.pay_on_delivery end,
    escalation = case when 'escalation' = any (p_money_fields)
                      then excluded.escalation else jobs.escalation end;

  update public.jobs
    set active = false, archived_at = now()
    where active = true and not (id = any (ids));

  update public.settings
    set priority_order = coalesce((
      select array_agg(x order by ord)
      from unnest(priority_order) with ordinality as t(x, ord)
      where x = any (ids)
    ), '{}')
    where id = 1;
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. Goal category
-- ---------------------------------------------------------------------------
-- Pointed at swimlanes (0010), which Admin already manages, so the categories
-- a goal can carry and the swimlanes a board can be grouped into are one list
-- rather than two that drift.
alter table public.goal_item
  add column if not exists swimlane_id uuid references public.swimlanes(id) on delete set null;

create index if not exists goal_item_swimlane_idx on public.goal_item (swimlane_id);

comment on column public.goal_item.swimlane_id is
  'Goal Category. Set on any goal, sub-goal or initiative; the swimlane a '
  'board groups by later is this same list.';


-- >>>>> supabase/migrations/0029_my_week.sql
-- 0029_my_week.sql
--
-- Two small things My Week needs, and nothing else.
--
-- 1. HOW'S MY DAY. One row per person per day. It is deliberately tiny: five
--    faces and an optional line. The value is not any single day's answer, it
--    is the run of them -- which is why the primary key is (person, date) and
--    a second click the same day CHANGES the answer rather than adding one.
--
-- 2. IMAGE QUOTES. The Drive folder they live in is not public, and enumerating
--    a Drive folder needs an API key even when it is. So the links are held
--    here and pasted in from Admin -- one row per image, one shown per day,
--    the same one for everybody.
--
-- ASCII only, safe to re-run.

-- ---------------------------------------------------------------------------
-- 1. How's my day
-- ---------------------------------------------------------------------------
create table if not exists public.day_mood (
  person_id  uuid not null references public.profiles(id) on delete cascade,
  on_date    date not null,
  -- five, and only five. A ten-point scale invites deliberation; five faces
  -- get answered honestly in the second before somebody thinks about it.
  mood       text not null,
  note       text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (person_id, on_date),
  constraint day_mood_scale check (mood in ('great', 'good', 'ok', 'low', 'rough'))
);

create index if not exists day_mood_date_idx on public.day_mood (on_date desc);

alter table public.day_mood enable row level security;

-- How somebody says their day is going is theirs. Managers see a team's shape
-- through the API, which walks reports_to; this is the backstop.
drop policy if exists day_mood_own on public.day_mood;
create policy day_mood_own on public.day_mood
  for select to authenticated
  using (person_id = auth.uid() or public.is_admin());

comment on table public.day_mood is
  'How each person said their day was going. One row per person per day; '
  'answering again the same day replaces the answer rather than adding one.';

-- ---------------------------------------------------------------------------
-- 2. Image quotes
-- ---------------------------------------------------------------------------
create table if not exists public.image_quote (
  id         uuid primary key default gen_random_uuid(),
  -- as pasted. A Google Drive share link is converted to a viewable URL when
  -- it is read, so whoever adds one does not have to know the trick.
  url        text not null,
  caption    text,
  active     boolean not null default true,
  sort_order int not null default 0,
  added_by   uuid references public.profiles(id),
  created_at timestamptz not null default now()
);

create index if not exists image_quote_active_idx on public.image_quote (active, sort_order);

alter table public.image_quote enable row level security;

drop policy if exists image_quote_read on public.image_quote;
create policy image_quote_read on public.image_quote
  for select to authenticated
  using (true);

comment on table public.image_quote is
  'Image quotes for My Week. A CACHE of a public Drive folder, refreshed from '
  'Admin. One is chosen per day from the active rows, the same one for '
  'everybody, so a day has a picture rather than a shuffle.';

-- Which folder to read them from. Held as a setting rather than in code so the
-- folder can be changed without a deploy -- and cached into image_quote above,
-- so a bad morning at Google leaves yesterday's pictures working instead of a
-- blank panel.
-- Guarded, because app_settings comes from 0017 and this file must not fail
-- on a database where that has not been pasted yet. The day_mood and
-- image_quote tables above are the part My Week actually needs; the folder id
-- can be typed into Admin instead.
do $$
begin
  if to_regclass('public.app_settings') is not null then
    execute 'alter table public.app_settings add column if not exists quote_folder text';
    execute $q$update public.app_settings
                 set quote_folder = '18YpET3C1DOgSssADYfB8qTzZdJbJNaqI'
               where id = true and coalesce(quote_folder, '') = ''$q$;
  end if;
end $$;


-- >>>>> supabase/migrations/0030_material_kitting.sql
-- 0030_material_kitting.sql
--
-- Material Kitting: a checklist line grows a date, an owner, a running note,
-- and the ability to BE a task.
--
-- The question this answers, asked by Dr Raghu: "is it possible for it to be a
-- TASK and a kitting material, since it will have a date? It will prevent a
-- lot of duplication."
--
-- Yes -- but not by making every checklist line a task. Eight lines on a
-- hundred and five jobs is eight hundred and forty tasks, and Tasking would
-- become a bill of materials nobody could read. So:
--
--   THE MATERIAL ROW IS THE RECORD. It carries the date and the owner.
--   A ROW CAN BE PROMOTED to a task when somebody actually has to chase it,
--   and the link is kept in task_id.
--   THE TWO ARE THEN HELD IN STEP, both ways, by the API: receiving the
--   material closes its task, and closing the task receives the material.
--
-- That is what prevents the duplication. Two records that merely LOOK the same
-- are not the problem; two records that drift apart are, and a link plus a
-- mirror is what stops that.
--
-- ASCII only, safe to re-run.

-- ---------------------------------------------------------------------------
-- 1. The new columns
-- ---------------------------------------------------------------------------
alter table public.materials add column if not exists due      date;
alter table public.materials add column if not exists who      text;
alter table public.materials add column if not exists note     text;
alter table public.materials add column if not exists task_id  uuid references public.manual_tasks(id) on delete set null;
alter table public.materials add column if not exists updated_at timestamptz not null default now();

comment on column public.materials.due is
  'Receivable date -- when this item is due in. The thing that makes a kitting '
  'line a task.';
comment on column public.materials.task_id is
  'Set when the line has been promoted to a task. The API mirrors status both '
  'ways, so the two can never drift.';

create index if not exists materials_due_idx on public.materials (due) where due is not null;
create index if not exists materials_task_idx on public.materials (task_id) where task_id is not null;

-- ---------------------------------------------------------------------------
-- 2. Three statuses, not two
-- ---------------------------------------------------------------------------
-- 'Pending' becomes 'Yet to receive' -- the same state, said the way the shop
-- floor says it. Renaming BEFORE the constraint changes, or every existing row
-- fails the new check.
alter table public.materials drop constraint if exists materials_status_check;

update public.materials set status = 'Yet to receive' where status = 'Pending';

alter table public.materials
  add constraint materials_status_check
  check (status in ('Yet to receive', 'Received', 'QC Defective'));

alter table public.materials alter column status set default 'Yet to receive';

-- ---------------------------------------------------------------------------
-- 3. Comments on a kitting line
-- ---------------------------------------------------------------------------
-- Same shape as task_comments (by/at/body), so the two read alike wherever
-- they are shown side by side.
create table if not exists public.material_comment (
  id          uuid primary key default gen_random_uuid(),
  material_id uuid not null references public.materials(id) on delete cascade,
  by          text,
  at          timestamptz not null default now(),
  body        text not null
);

create index if not exists material_comment_idx on public.material_comment (material_id, at desc);

alter table public.material_comment enable row level security;

drop policy if exists material_comment_read on public.material_comment;
create policy material_comment_read on public.material_comment
  for select to authenticated
  using (true);

comment on table public.material_comment is
  'Comments against one kitting line -- where a delay gets explained, next to '
  'the item it is delaying.';


-- >>>>> supabase/migrations/0031_erp_update_queue.sql
-- 0031_erp_update_queue.sql
--
-- The ERP Update queue.
--
-- Genie has always been downstream of the ERP: the morning file arrives and
-- the board is redrawn. Editing a job here has therefore only ever been a note
-- of intent, kept in a JavaScript array that died with the browser tab. That
-- is why "Update to ERP" could show a session's changes and nothing more.
--
-- This makes the queue real, so somebody can take a day's corrections and put
-- them back into the ERP in one pass rather than remembering them.
--
-- Three rules the table exists to enforce:
--
--   ONLY WHAT CHANGED. A row is written when a value actually differs from
--   what was there. Re-typing 40% over 40% queues nothing.
--
--   ONE PENDING ROW PER JOB AND FIELD. Editing the same field three times
--   before an export leaves ONE line carrying the latest value, not three to
--   apply in order. What Pankaj needs is the answer, not the history.
--
--   THE JOB ID LEADS. Every export line starts with it, so a row can be found
--   and overwritten in the ERP without matching on anything softer.
--
-- ASCII only, safe to re-run.

create table if not exists public.erp_update (
  id          uuid primary key default gen_random_uuid(),
  job_id      text not null,
  -- the column as Genie names it (tdd, kit, pct, note, escalation, amt_needed)
  field       text not null,
  -- and as the ERP names it, so the export needs no lookup table
  label       text not null,
  old_value   text,
  new_value   text,
  changed_by  text,
  changed_at  timestamptz not null default now(),
  -- null while it still has to go into the ERP
  exported_at timestamptz,
  exported_by text
);

create index if not exists erp_update_pending_idx
  on public.erp_update (job_id, field) where exported_at is null;
create index if not exists erp_update_changed_idx
  on public.erp_update (changed_at desc);

alter table public.erp_update enable row level security;

-- Everyone signed in can see what is queued -- it is a list of corrections to
-- this company's own data, and hiding it only means two people make the same
-- one. Writing goes through /api/job-field under the service role.
drop policy if exists erp_update_read on public.erp_update;
create policy erp_update_read on public.erp_update
  for select to authenticated
  using (true);

comment on table public.erp_update is
  'Field changes made in Genie that still have to be applied in the ERP. One '
  'pending row per job and field, carrying the latest value; cleared by '
  'marking it exported once it has been uploaded.';


-- >>>>> supabase/migrations/0032_task_date_history.sql
-- 0032_task_date_history.sql
--
-- A task remembers the date it was FIRST promised, and every move since.
--
-- The problem, seen the moment dragging worked: a task due 11 August was
-- dragged onto the 18th and stopped being late. Nothing recorded that it had
-- ever been late, and nothing recorded that anybody had moved it. Lateness had
-- become a thing you could delete by dragging.
--
-- Goals settled this in 0019 with original_due and push_count -- "carried days
-- and pushes are counted against the date first committed, not the one on
-- screen". Tasks now work the same way:
--
--   ORIGINAL_DUE is the first date ever promised and never changes again.
--   PUSH_COUNT says how many times it has moved.
--   TASK_DATE_LOG says who moved it, when, and from what to what.
--
-- The board reads original_due for lateness. So a task pushed from the 11th to
-- today still reads late, because it is.
--
-- ASCII only, safe to re-run.

-- ---------------------------------------------------------------------------
-- 1. The two columns, on both kinds of task
-- ---------------------------------------------------------------------------
alter table public.manual_tasks add column if not exists original_due date;
alter table public.manual_tasks add column if not exists push_count int not null default 0;
alter table public.erp_tasks    add column if not exists original_due date;
alter table public.erp_tasks    add column if not exists push_count int not null default 0;

-- Everything already on the board is treated as promised on the date it
